M = 10 ** 9 + 7


def pw(a, n):
    if n == 0:
        return 1
    b = pw(a, n // 2)
    return b * b % M * (a if n % 2 == 1 else 1) % M


def obr(x):
    return pw(x, M - 2)


def cnk(n, k):
    return fact[n] * obr(fact[k]) % M * obr(fact[n - k]) % M


